# We'll count consecutive matches between arr[i] and arr[i-m].
# If we get enough matches, it means the pattern repeats k times.

def containsPattern(arr, m, k):
    count = 0
    for i in range(m, len(arr)):
        if arr[i] == arr[i - m]:
            count += 1
        else:
            count = 0
        if count == m * (k - 1):
            return True
    return False
